const fields=[['wetKg','Vehicle wet mass','kg',10,120,.1],['count','Probes per vehicle','count',1,7,1],['probeKg','Complete probe mass','kg',.5,10,.05],['diameterM','Aeroshell diameter','m',.4,2,.01],['heightM','Aeroshell envelope height · NASA angle convention','m',.1,2,.000001],['orbitKm','Circular orbit','km',150,1000,1],['periapsisKm','Vacuum periapsis proxy','km',1,149,1],['marginPct','Delta-v planning allowance','%',0,100,1],['rho','Atmospheric density','kg/m³',.003,.04,.001],['cd','Parachute effective Cd','',.2,1.5,.05],['probeChuteM','Probe canopy diameter','m',.1,2,.01],['pcmChuteM','PCM canopy diameter','m',.5,5,.05],['suspendedKg','PCM suspended mass assumption','kg',1,100,.1],['rangeKm','Relay slant range','km',50,4000,10],['rfW','Peak RF output','W',.1,50,.1],['receiverDbm','Assumed receiver threshold','dBm',-150,-80,1],['lossDb','RF implementation losses','dB',0,30,.5],['dutySec','Transmit burst per minute','s',.1,60,.1],['inertia','Assumed attitude inertia','kg m²',.1,20,.1],['jetN','One jet thrust','N',.01,1,.01],['leverM','Jet lever arm','m',.05,1,.01],['jetSeconds','Cumulative jet seconds','s',0,3000,1],['operationHours','Surface operation goal','h',1,168,1],['energyWh','Usable probe energy assumption','Wh',1,100,1],['averageW','Average probe load','W',.01,5,.01]];
function init(){config=$('#config').value;protocol=$('#protocol').value;resetFlightOptions();p={...DEFAULTS,...CONFIGS[config],heightM:aeroshellHeight(CONFIGS[config].diameterM),orbitKm:INITIAL_ORBIT_KM,inertia:config==='A'?1.5:3.75,suspendedKg:CONFIGS[config].wetKg};events=presentationEvents(p.count,protocol);completed=0;clock=0;playing=false;lastFrame=null;lastTx=-1;lastLog=-1;$('#eventLog').replaceChildren();$('#packet').textContent='No transmission attempted.';renderPhaseControls();renderControls();renderEngineering();}
function renderPhaseControls(){
 $('#phaseSelect').innerHTML=PRESENTATION_PHASES.map(x=>`<option value="${x.id}">${x.title}</option>`).join('');
 $('#phaseRail').innerHTML=PRESENTATION_PHASES.map(x=>`<button type="button" data-phase="${x.id}">${x.title}</button>`).join('');
 $('#eventSelect').innerHTML=events.map((e,i)=>`<option value="${i}">${i+1}. ${escape(e.label)}</option>`).join('');$('#scrub').max=events.at(-1).end;$('#scrub').value=0;
}
function renderControls(){$('#controls').innerHTML=fields.map(([key,label,unit,min,max,step])=>`<div class="range-control"><label for="trade-range-${key}">${label}${unit?' ('+unit+')':''}</label><div class="range-pair"><input id="trade-range-${key}" data-key="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${p[key]}" aria-label="${label} slider"><input data-key="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${p[key]}" aria-label="${label} value"></div></div>`).join('');}
function renderEngineering(){p.heightM=aeroshellHeight(p.diameterM);for(const input of $('#controls').querySelectorAll('[data-key=heightM]')){input.value=p.heightM;input.disabled=true;input.title='Derived envelope: 0.75D assumed backshell + (D/2)tan20° forebody cone envelope. Nose blend is not sized.';}let massPlan;try{if(config==='A'){massPlan=precursorMassPlan(p.wetKg,getFlightInspection().options);p.massScale=massPlan.scale;p.probeKg=massPlan.probeTotalKg/p.count;setPrecursorMassScale(massPlan.scale);for(const input of $('#controls').querySelectorAll('[data-key=probeKg]')){input.value=p.probeKg;input.disabled=true;input.title='Calculated from proportional K-class mass allocation';}}lastResult=calculate(p);$('#inputError').textContent='';}catch(e){lastResult=null;$('#inputError').textContent='No current engineering solution: '+e.message;for(const id of ['results','massTable','calculationDetails'])$( '#'+id).replaceChildren();updateFlightPanel(config,p);return;}const r=lastResult;
 const cards=[['Ideal Δv',fmt(r.dv)+' m/s'],['With planning allowance',fmt(r.designDv)+' m/s'],['Momentum-equivalent demand',fmt(r.impulseEquivalent/1000,3)+' kN s'],['Non-probe mass available',fmt(r.nonProbe)+' kg'],['Probe terminal-speed screen',fmt(r.probeTerminal,1)+' m/s'],['PCM terminal-speed screen',fmt(r.pcmTerminal,1)+' m/s'],['Illustrative link margin',fmt(r.linkMargin,1)+' dB'],['Probe energy remaining',fmt(r.energyRemaining,1)+' Wh']];
 $('#results').innerHTML=cards.map(([label,value])=>`<div class="stat"><b>${value}</b><span>${label}</span></div>`).join('');
 const rows=config==='A'?massPlan.allocations:ALLOCATIONS.map(row=>({name:row[0],sourceKg:row[2],kg:row[2]}));
 $('#massTable').innerHTML=`<p>Aeroshell geometry: NASA-style forebody half-angle 70° from the symmetry axis (20° from the heat-shield plane). Diameter ${fmt(p.diameterM,3)} m; total provisional envelope ${fmt(p.heightM,3)} m = assumed backshell 0.75D + forebody cone envelope (D/2)tan20°. At D = 0.8 m these are 0.600 + 0.146 = 0.746 m. Backshell proportion is a packaging assumption; spherical nose and shoulder blends require CAD sizing. The NASA forebody angle does not set the backshell slope. <a href="#aeroshell-geometry-requirement">Requirement and NASA references</a>. Drag coefficients, inertia and TPS properties remain independent assumptions.</p>`+'<table><thead><tr><th>Subsystem</th><th>Rev09 source kg</th><th>Current allocation kg</th></tr></thead><tbody>'+rows.map(row=>`<tr><td>${escape(row.name)}</td><td>${fmt(row.sourceKg,3)}</td><td>${fmt(row.kg,3)}</td></tr>`).join('')+`<tr><th>Total</th><th>${fmt(CONFIGS[config].wetKg,3)}</th><th>${fmt(rows.reduce((sum,row)=>sum+row.kg,0),3)}</th></tr></tbody></table>`+(config==='A'?`<p>K-class propulsion allocation: assumed dry motor/module ${fmt(massPlan.dryKg,3)} kg + calculated propellant ${fmt(massPlan.propellantKg,3)} kg + initial nitrogen ${fmt(massPlan.nitrogenKg,3)} kg = ${fmt(massPlan.propulsionKg,3)} kg. All other allocations, including reserve, scale by ${fmt(massPlan.scale,5)} (${fmt(100*(1-massPlan.scale),2)}% reduction). ${p.count} probes share ${fmt(massPlan.probeTotalKg,3)} kg; each is ${fmt(p.probeKg,3)} kg. The flight model uses a proportionally scaled retained carrier dry mass of ${fmt(massPlan.carrierDryKg,3)} kg.</p><p>Dry motor mass and Isp are assumptions, not a selected motor specification. Scaling is a planning allocation, not demonstrated hardware mass closure. Nitrogen is included once in propulsion. Tank and plumbing hardware remain within the GNC allocation; component boundaries require review.</p>`:`<p>B source allocations are a fixed 50 kg reference, not a current mass plan. Current wet mass ${fmt(p.wetKg)} kg; source-to-current difference ${fmt(p.wetKg-50)} kg. Current probe load ${fmt(r.probeTotal)} kg versus 14 kg source allocation; available non-probe mass ${fmt(r.nonProbe)} kg. Mission wet total ${fmt(lastResult.missionWet)} kg. Component reallocation and closure are required for off-baseline trades.</p>`);
 $('#calculationDetails').innerHTML=`<p>β = m / (1.5 A) = ${fmt(r.beta)} kg/m². A = ${fmt(r.area,4)} m².</p><p>Free-space loss ${fmt(r.fspl,1)} dB; received power ${fmt(r.rx,1)} dBm. Receiver threshold ${fmt(p.receiverDbm,1)} dBm. No relay access or waveform agreement is implied.</p><p>Keyed DC power ${fmt(r.txDc,1)} W; nominal transmit energy ${fmt(r.txWhHour,3)} Wh/hour. Packet overhead and acquisition energy are additional.</p><p>Independent one-jet screen (not the three-maneuver flight budget): torque ${fmt(r.torque,3)} N m; ideal symmetric 90° slew ${fmt(r.slew90,1)} s; modeled gas for cumulative jet time ${fmt(r.gasKg*1000,2)} g. Inertia ${fmt(p.inertia)} kg m² is an assumption${config==='B'?' requiring separate B sizing':''}.</p><p>Probe surface load ${fmt(r.scienceEnergy,2)} Wh over ${p.operationHours} h, against ${p.energyWh} Wh usable. Source B example: 14.4 Wh load from 20 Wh usable. A energy capacity remains a trade input.</p><p>Guidance example: ${fmt(r.exampleGuidanceWh,2)} Wh before conversion and thermal losses; 2× planning value ${fmt(2*r.exampleGuidanceWh,2)} Wh. Independent carrier energy example: 14.8 Wh nominal.</p><p>Impulse shown is mΔv, not delivered motor impulse. It omits changing mass and thrust-curve effects. No complete entry/heating solver is represented by these cards.</p>`;
 updateFlightPanel(config,p);renderOperations();}
function renderOperations(){
 const c=p,state=timelineState(events,clock),e=state.event,phase=PRESENTATION_PHASES.find(x=>x.id===e.group),science=SCIENCE_PROTOCOLS[protocol];completed=state.completed;
 $('#phase').textContent=phase.title;$('#eventTitle').textContent=state.done?'Mission walkthrough complete':e.label;$('#eventDetail').textContent=e.detail;
 $('#phaseDescription').textContent=phase.description;$('#phaseSource').textContent=phase.source;$('#probeCount').textContent=`${c.count} × ${fmt(c.probeKg,2)} kg`;$('#wetMass').textContent=`${c.wetKg} kg`;$('#clock').textContent=fmt(clock,1)+' s';
 $('#phaseSelect').value=e.group;$('#scrub').value=clock;$('#progressLabel').textContent=`Step ${state.index+1} of ${events.length} · ${fmt(100*clock/state.total,0)}%`;$('#eventSelect').value=state.index;
 for(const button of document.querySelectorAll('#phaseRail button')){button.classList.toggle('active',button.dataset.phase===e.group);button.setAttribute('aria-current',button.dataset.phase===e.group?'step':'false');}
 const bits=statusBits(events,completed,c.count),labels=['Health check','Host separated','Attitude confirmed','Burn confirmed','Carrier extracted','Probe 1 released','Probe 2 released','Probe 3 released','Carrier landed','Probe 4 released','Probe 5 released','Probe 6 released','Probe 7 released'];$('#bits').innerHTML=labels.map((label,i)=>{const used=i<=4||i===8||(i>=5&&i<=7?i-4<=c.count:i-5<=c.count);return `<div class="bit ${bits[i]?'on':''} ${used?'':'not-applicable'}" aria-label="Bit ${i}: ${label}; ${used?(bits[i]??0):'Not fitted'}"><span class="status-bit-index">Bit ${i}</span><strong>${used?(bits[i]??0):'N/A'}</strong><span class="status-bit-label">${label}</span>${used?'':'<small>Not fitted</small>'}</div>`;}).join('');
 $('#bitNote').textContent=p.count!==CONFIGS[config].count?`Off-baseline ${p.count}-probe trade: ${bits.length} transmitted positions. The panel retains all 13 positions; unused probe positions are N/A.`:config==='A'?'13 positions displayed: A transmits its 9 core bits; bits 9–12 are marked B only and are not included in A’s packet.':'13 carrier payload bits: core bits 0–8 plus drops 4–7 in bits 9–12. Science and data return continue after all bits are latched.';
 $('#bitDefinitions').innerHTML=events.filter(x=>Number.isInteger(x.bit)).map(x=>`<p>Bit ${x.bit}: ${x.label}</p>`).join('');
 const jetsActive=e.id==='host-separation'||e.id==='cold-gas-slew'||e.id==='heat-shield-slew';$('#jets').innerHTML=Array.from({length:6},(_,i)=>`<div class="bit ${jetsActive&&i%2===Math.floor(clock*2)%2?'on':''}">Jet ${i+1}</div>`).join('');
 const liveFlight=getCurrentFlight(),liveTime=reviewMissionTime(liveFlight,events,state);state.telemetry=renderMissionReadouts(liveFlight,liveTime,p,state);currentReview={state,time:liveTime,telemetry:state.telemetry};renderDashboard({flight:liveFlight,telemetry:state.telemetry,state,config,inputs:p,playing,speed:$('#speed').value});$('#scene').innerHTML=missionScene({state,c,events,flight:liveFlight});drawTrend(state);
 $('#scienceReviewLive').innerHTML=scienceReviewMarkup(c,protocol);
 $('#protocolSummary').textContent=`${science.name}. ${science.sample}. ${science.conditions}. Proposed experimental sequence; no laboratory measurement is generated.`;
 $('#scienceReadout').hidden=e.group!=='science';$('#scienceStage').textContent=e.label;
 $('#scienceInterpretation').textContent=e.scienceStage==='controls'?'Review test/control differences, abiotic reactions, leakage, sorption and detector validity. No detection verdict is produced by this animation.':'Test and control records remain separate. Detector counts, yields and biological outcomes are not simulated.';
 $('#demoMetrics').textContent=`Review event ${Math.min(state.index+1,events.length)}/${events.length}. The physical telemetry clock is compressed by review phase. Event labels select review focus; simultaneous probe descents use their common physical time. Science incubation remains illustrative. Source science goal ${c.operationHours} h; ${c.bufferMB} MB/probe. Independent carrier transmission attempts at synthetic 60-second intervals; reception unverified.`;
 if(lastLog!==completed){lastLog=completed;$('#eventLog').innerHTML=events.slice(0,completed).reverse().map(x=>`<p>${fmt(x.end,0)} playback s · ${escape(x.phase)} · ${escape(x.label)}${Number.isInteger(x.bit)?' · bit '+x.bit:''}</p>`).join('')||'<p>No completed review events.</p>';}
 if(state.done)playing=false;$('#play').textContent=state.done?'Replay':playing?'Playing':'Start';
}
function drawTrend(state){
 const total=state.total,points=events.map(e=>{const order=PRESENTATION_PHASES.findIndex(x=>x.id===e.group),height=[20,22,25,60,85,100,117,120,120][order];return `${50+e.start/total*800},${height}`;}).join(' ');
 $('#trend').innerHTML=`<path d="M50 20 V125 H850" fill="none" stroke="#405873"/><polyline points="${points}" stroke="#72dfca" fill="none" stroke-width="3"/><line x1="${50+clock/total*800}" x2="${50+clock/total*800}" y1="15" y2="130" stroke="#ffcd82"/><text x="60" y="15" fill="#aebfd4" font-size="12">Normalized mission-stage trend · no altitude prediction</text><text x="50" y="150" fill="#aebfd4" font-size="12">Rideshare / orient</text><text x="365" y="150" fill="#aebfd4" font-size="12">Entry / deployment</text><text x="650" y="150" fill="#aebfd4" font-size="12">Science / return</text>`;
}
function advance(){playing=false;const state=timelineState(events,clock);clock=state.done?state.total:state.event.end;renderOperations();transmit();}
function previous(){playing=false;const state=timelineState(events,clock);clock=events[Math.max(0,state.index-1)].start;renderOperations();}
function seekPhase(group){playing=false;clock=events.find(x=>x.group===group).start;lastLog=-1;renderOperations();transmit();}
function transmit(){const bits=statusBits(events,timelineState(events,clock).completed,p.count);$('#packet').textContent=`Synthetic transmit attempt at ${fmt(clock,0)} playback s: ${[...bits].reverse().join('')} (MSB→LSB). Reception unverified.`;}
function filterRequirements(){const query=$('#reqSearch').value.toLowerCase(),family=$('#reqFamily').value,evidence=$('#reqEvidence').value;const filtered=requirements.filter(r=>(!family||r.id.startsWith(family+'-'))&&requirementEvidenceMatches(r,query,evidence));$('#reqCount').textContent=`${filtered.length} of ${requirements.length} source requirements · reviewed baseline evidence`;$('#reqList').innerHTML=filtered.map(requirementEvidenceMarkup).join('');}
$('#eventSelect').onchange=e=>{playing=false;clock=events[Number(e.target.value)].start;renderOperations();};$('#config').addEventListener('change',init);$('#protocol').addEventListener('change',init);$('#phaseSelect').addEventListener('change',e=>seekPhase(e.target.value));$('#phaseRail').addEventListener('click',e=>{if(e.target.dataset.phase)seekPhase(e.target.dataset.phase);});$('#scrub').addEventListener('input',e=>{playing=false;clock=Number(e.target.value);lastLog=-1;renderOperations();});$('#previous').onclick=previous;$('#defaults').addEventListener('click',init);$('#missionDefaults').onclick=init;$('#reset').addEventListener('click',init);$('#play').onclick=()=>{if(timelineState(events,clock).done){clock=0;lastLog=-1;}playing=true;lastFrame=null;renderOperations();};$('#pause').onclick=()=>{playing=false;renderOperations();};$('#step').onclick=advance;
let tradeInputTimer;$('#controls').addEventListener('input',e=>{if(!e.target.dataset.key)return;const value=Number(e.target.value);if(!e.target.checkValidity()||!Number.isFinite(value)){$('#inputError').textContent='Enter a number inside the displayed control range.';return;}const key=e.target.dataset.key;p[key]=value;for(const input of $('#controls').querySelectorAll('input'))if(input.dataset.key===key&&input!==e.target)input.value=e.target.value;clearTimeout(tradeInputTimer);tradeInputTimer=setTimeout(()=>{if(key==='count'){events=presentationEvents(p.count,protocol);renderPhaseControls();clock=Math.min(clock,events.at(-1).end);}renderEngineering();},90);});
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({release:'5.1',source:'FDS-001 Rev0.9',configuration:config,inputs:p,outputs:lastResult,flight:getCurrentFlight(),impactAssumptions:getSoilInputs(),penetrationReferences:PENETRATION_EVIDENCE,depthUncertaintyAssumptions:DEPTH_UNCERTAINTY,scienceResourceReview:scienceResourceCheck(p,protocol),qualification:'Preliminary analytical screens only; no flight reliability inference'},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='FREYA_Revision_5_1_current_trade.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('#reqSearch').oninput=filterRequirements;$('#reqFamily').onchange=filterRequirements;
function animate(now){if(lastFrame===null)lastFrame=now;const dt=Math.min(.2,(now-lastFrame)/1000);lastFrame=now;if(playing){clock=Math.min(events.at(-1).end,clock+dt*Number($('#speed').value));const tx=Math.floor(clock/60);if(tx>lastTx){lastTx=tx;transmit();}renderOperations();}requestAnimationFrame(animate);}
requestAnimationFrame(animate);
initMountTrade();initDashboard();initRequirementEvidence(filterRequirements);initMissionTradePanel(renderOperations);initFlightPanel();initEntryDesign(getFlightInspection,onFlightChange);onFlightChange(()=>{if(config==='A'){try{const plan=precursorMassPlan(p.wetKg,getFlightInspection().options);if(Math.abs((p.massScale??0)-plan.scale)>1e-10){renderEngineering();return;}}catch(e){$('#inputError').textContent=e.message;}}renderOperations();});init();fetch('data/revision51/requirements.json').then(r=>{if(!r.ok)throw Error('Requirements unavailable');return r.json();}).then(r=>{requirements=r;filterRequirements();}).catch(e=>$('#reqCount').textContent=e.message);

initCalculationInspector(()=>({configuration:config,inputs:{...p},soil:getSoilInputs(),flight:getFlightInspection(),result:lastResult,review:currentReview}),()=>{playing=false;$('#play').textContent='Start';$('#flightPause').click();$('#flightPlay').textContent='Play flight';});

